('601a4acd-6fd9-4f6c-9a59-79ed5d901fb8', 'user', 'import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import { getAllModels } from "../../services/apiServices";

export const fetchModels = createAsyncThunk(
  "model/fetchModels",
  async (_, { rejectWithValue }) => {
    try {
      const data = await getAllModels();
      return data.models;
    } catch (error) {
      console.error("Error fetching models:", error);
      return rejectWithValue(error.response?.data || "Failed to fetch models");
    }
  }
);

const initialState = {
  models: [],
  selectedModelId: null,
  selectedModelMode: ''chat'', // NEW: track the mode
  loading: false,
  error: null,
};

const modelSlice = createSlice({
  name: "model",
  initialState,
  reducers: {
    setSelectedModel: (state, action) => {
      state.selectedModelId = action.payload;
      
      const selectedModel = state.models.find(model => model.id === action.payload);
      
      // Always set a mode, even if capabilities are missing
      if (selectedModel) {
        const caps = selectedModel.capabilities || {};
        if (caps.direct_sql) {
          state.selectedModelMode = ''direct_sql'';
        } else if (caps.sql_gpt) {
          state.selectedModelMode = ''sql_gpt'';
        } else {
          state.selectedModelMode = ''chat'';
        }
      } else {
        state.selectedModelMode = ''chat''; // fallback
      }
    },
    resetModelState: (state) => {
      state.models = [];
      state.selectedModelId = null;
      state.selectedModelMode = ''chat''; // NEW: reset mode
      state.loading = false;
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchModels.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchModels.fulfilled, (state, action) => {
        state.loading = false;
        state.models = action.payload;

        // Only set default if no model is currently selected
        if (!state.selectedModelId) {
          // Look for gpt-5-chat specifically
          const gpt5Chat = action.payload.find(m => 
            m.name?.toLowerCase().includes("gpt-5-chat")
          );
          
          // Fallback to gpt-5 if gpt-5-chat not found
          const gpt5 = gpt5Chat || action.payload.find(m => 
            m.name?.toLowerCase().includes("gpt-5")
          );
          
          // Set selected model ID and mode
          const selectedModel = gpt5 || action.payload[0];
          if (selectedModel) {
            state.selectedModelId = selectedModel.id;
            
            // NEW: Set the mode based on capabilities
            if (selectedModel.capabilities?.direct_sql) {
              state.selectedModelMode = ''direct_sql'';
            } else if (selectedModel.capabilities?.sql_gpt) {
              state.selectedModelMode = ''sql_gpt'';
            } else {
              state.selectedModelMode = ''chat'';
            }
          }
        } else {
          // NEW: Update mode for existing selected model
          const selectedModel = action.payload.find(model => model.id === state.selectedModelId);
          if (selectedModel) {
            if (selectedModel.capabilities?.direct_sql) {
              state.selectedModelMode = ''direct_sql'';
            } else if (selectedModel.capabilities?.sql_gpt) {
              state.selectedModelMode = ''sql_gpt'';
            } else {
              state.selectedModelMode = ''chat'';
            }
          }
        }
      })
      .addCase(fetchModels.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || "Failed to load models";
      });
  },
});

export const { setSelectedModel, resetModelState } = modelSlice.actions;
export default modelSlice.reducer;

