('c7d13f89-2aab-4b19-ac45-b54b2c08d92a', 'user', '{messages.length > 0 && (
  <Box sx={{ p: 2 }}>
    <Box sx={{ 
      width: "100%", 
      maxWidth: "768px", 
      position: "relative", 
      margin: "0 auto",
      display: "flex",
      alignItems: "flex-end",
    }}>
      <Box sx={{ 
        position: "relative", 
        flex: 1,
        display: "flex",
        alignItems: "flex-end",
      }}>
        <TextareaAutosize
          minRows={1}
          maxRows={8}
          placeholder="Type your message..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          style={{
            width: "100%",
            border: `1px solid ${theme.palette.divider}`,
            borderRadius: 12,
            padding: "12px 52px 12px 16px",
            fontSize: 16,
            resize: "none",
            backgroundColor: theme.palette.background.paper,
            color: theme.palette.text.primary,
            fontFamily: theme.typography.fontFamily,
            lineHeight: 1.5,
            paddingRight: "52px",
            // Custom scrollbar styles
            scrollbarWidth: ''thin'',
            scrollbarColor: `${theme.palette.divider} transparent`,
            ''&::-webkit-scrollbar'': {
              width: ''6px'',
            },
            ''&::-webkit-scrollbar-track'': {
              background: ''transparent'',
              borderRadius: ''3px'',
            },
            ''&::-webkit-scrollbar-thumb'': {
              background: theme.palette.divider,
              borderRadius: ''3px'',
            },
            ''&::-webkit-scrollbar-thumb:hover'': {
              background: theme.palette.mode === ''dark'' ? ''#555'' : ''#999'',
            },
          }}
        />
        <IconButton
          onClick={isStreaming ? stopStreaming : handleSend}
          disabled={!input.trim() && !isStreaming}
          sx={{
            position: "absolute",
            right: 8,
            bottom: 8,
            width: 32,
            height: 32,
            backgroundColor: isStreaming
              ? theme.palette.error.main
              : (input.trim() ? theme.palette.primary.main : theme.palette.action.disabled),
            color: "#fff",
            "&:hover": {
              backgroundColor: isStreaming
                ? theme.palette.error.dark
                : (input.trim() ? theme.palette.primary.dark : theme.palette.action.disabled),
            },
            "&.Mui-disabled": {
              backgroundColor: theme.palette.action.disabled,
              color: theme.palette.action.disabledBackground,
            },
          }}
        >
          {isStreaming ? <StopIcon sx={{ fontSize: 16 }} /> : <SendIcon sx={{ fontSize: 16 }} />}
        </IconButton>
      </Box>
    </Box>
  </Box>
)}
