        {[1, 2, 3, "+", 4, 5, 6, "-", 7, 8, 9, "*", ".", 0, "/", "="].map(
          (item) => (
            <button
              key={item}
              onClick={() =>
                item === "=" ? handleCalculate() : handleClick(item)
              }
              style={{
